import { useEffect, useState } from "react";
import API from "../services/adminApi";
import "../styles/Providers.css";

const Providers = () => {
  const [providers, setProviders] = useState([]);
  const [search, setSearch] = useState("");
  const [selectedProvider, setSelectedProvider] = useState(null);

  const fetchProviders = async () => {
    try {
      const res = await API.get("/providers");
      setProviders(res.data);
    } catch (err) {
      console.log("Error fetching providers");
    }
  };

  useEffect(() => {
    fetchProviders();
  }, []);

  // ✅ Approve
  const handleApprove = async (id) => {
    if (!window.confirm("Approve this provider?")) return;
    await API.put(`/approve-provider/${id}`);
    fetchProviders();
  };

  // ✅ Reject (Set back to pending)
  const handleReject = async (id) => {
    if (!window.confirm("Set this provider back to pending?")) return;
    await API.put(`/reject-provider/${id}`);
    fetchProviders();
  };

  // ✅ Block / Unblock
  const handleBlock = async (id) => {
    if (!window.confirm("Change block status?")) return;
    await API.put(`/block-provider/${id}`);
    fetchProviders();
  };

  const filteredProviders = providers.filter((provider) =>
    provider.name.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="providers-container">
      <div className="providers-header">
        <h2>Providers Management</h2>

        <input
          type="text"
          placeholder="Search provider..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="search-input"
        />
      </div>

      <div className="table-wrapper">
        <table>
          <thead>
            <tr>
              <th>Name</th>
              <th>Email</th>
              <th>Phone</th>
              <th>Joined</th>
              <th>Approval</th>
              <th>Status</th>
              <th>Actions</th>
            </tr>
          </thead>

          <tbody>
            {filteredProviders.map((provider) => (
              <tr key={provider.user_id}>
                <td>{provider.name}</td>
                <td>{provider.email}</td>
                <td>{provider.phone || "-"}</td>
                <td>
                  {provider.created_at
                    ? new Date(provider.created_at).toLocaleDateString()
                    : "-"}
                </td>

                {/* Approval Status */}
                <td>
                  {provider.is_approved ? (
                    <span className="status-approved">Approved</span>
                  ) : (
                    <span className="status-pending">Pending</span>
                  )}
                </td>

                {/* Block Status */}
                <td>
                  {provider.is_blocked ? (
                    <span className="status-blocked">Blocked</span>
                  ) : (
                    <span className="status-active">Active</span>
                  )}
                </td>

                {/* Actions */}
                <td className="action-buttons">
                  {!provider.is_approved && (
  <button
    className="btn-approve"
    onClick={() => handleApprove(provider.user_id)}
  >
    Approve
  </button>
)}

{provider.is_approved && (
  <button
    className="btn-reject"
    onClick={() => handleReject(provider.user_id)}
  >
    Set Pending
  </button>
)}

<button
  className="btn-block"
  onClick={() => handleBlock(provider.user_id)}
>
  {provider.is_blocked ? "Unblock" : "Block"}
</button>

<button
  className="btn-view"
  onClick={() => setSelectedProvider(provider)}
>
  View
</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Provider Detail Modal */}
      {selectedProvider && (
        <div className="modal-overlay">
          <div className="modal">
            <h3>Provider Details</h3>

            <p><strong>Name:</strong> {selectedProvider.name}</p>
            <p><strong>Email:</strong> {selectedProvider.email}</p>
            <p><strong>Phone:</strong> {selectedProvider.phone}</p>
            <p>
              <strong>Approval:</strong>{" "}
              {selectedProvider.is_approved ? "Approved" : "Pending"}
            </p>
            <p>
              <strong>Status:</strong>{" "}
              {selectedProvider.is_blocked ? "Blocked" : "Active"}
            </p>

            <button onClick={() => setSelectedProvider(null)}>
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Providers;
